  function renderUsers(){if(backendUser?.role!=='admin')return;const users=campusData.users||[];$('accountsTable').innerHTML=users.map(u=>`<tr><td>${esc(u.display_name)}</td><td>${esc(u.username)}</td><td>${esc(u.role)}</td><td>${esc(u.student_id||'—')}</td><td><span class="risk-badge ${u.enabled?'risk-low':'risk-high'}">${u.enabled?'Enabled':'Disabled'}</span></td><td><button class="btn account-toggle" data-user="${u.id}" data-enabled="${u.enabled?'false':'true'}">${u.enabled?'Disable':'Enable'}</button></td></tr>`).join('')||'<tr><td colspan="6" class="no-data">No accounts found.</td></tr>';const events=campusData.audit||[];$('auditTable').innerHTML=events.map(e=>`<tr><td>${esc(new Date(e.at).toLocaleString())}</td><td>${esc(e.username||'System')}</td><td>${esc(e.action)}</td><td>${esc(e.detail||'—')}</td></tr>`).join('')||'<tr><td colspan="4" class="no-data">No activity recorded yet.</td></tr>';}
