  function setSignedIn(user){backendUser=user;document.body.classList.remove('student-mode');document.body.classList.add('authenticated');$('authGate').hidden=true;$('sideUserName').textContent=user.name;$('sideUserRole').textContent={admin:'Administrator · demo access',faculty:'Faculty · demo access',student:'Student · demo access'}[user.role]||'Campus demo';$('roleLabel').textContent={admin:'Administrator demo',faculty:'Faculty demo',student:'Student demo'}[user.role]||user.role;$('topAvatar').textContent=initials(user.name);$('logoutBtn').hidden=false;$('switchRoleBtn').hidden=false;$('studentPortal').hidden=user.role!=='student';document.querySelectorAll('#importBtn,#dataImportBtn,#exportBtn,#demoCsvBtn,#exportInterventions,#templateBtn,#dataTemplateBtn,#settingsBtn,#seedBtn').forEach(b=>b.hidden=user.role!=='admin');document.querySelector('[data-view="data"]').hidden=user.role==='faculty';if(user.role==='faculty')document.querySelector('[data-view="triage"]').click();if(user.role==='student')renderStudentPortal();}
  async function loadBackend(user){const [studentData,caseData]=await Promise.all([api('/api/students'),api('/api/cases')]);records=studentData.students;cases=caseData.cases;imported=true;importIssues=[];const termsIn=[...new Set(records.map(r=>r.term))].sort((a,b)=>termKey(a).localeCompare(termKey(b)));$('termSelect').innerHTML='<option value="all">All terms · latest per student</option>'+termsIn.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');$('termSelect').value='all';setSignedIn(user);if(user.role!=='student')render();await refreshCampus();clearInterval(campusTimer);campusTimer=setInterval(()=>refreshCampus().catch(e=>console.warn('Campus refresh:',e.message)),15000);}
