  function download(name,content,type='text/csv'){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
  const columns=['student_id','name','term','program','year','cgpa','backlogs','attendance','lms','engagement','aptitude','coding','interview','placement_readiness','updated_at'];
  function csvCell(v){let s=String(v??'');return /[",\n\r]/.test(s)?`"${s.replace(/"/g,'""')}"`:s;}
  function exportCsv(rows,name){download(name,[columns.join(','),...rows.map(r=>columns.map(k=>csvCell(r[k])).join(','))].join('\r\n'));}
  function parseCsv(text){let rows=[],row=[],v='',q=false;for(let i=0;i<text.length;i++){let c=text[i];if(q){if(c==='"'&&text[i+1]==='"'){v+='"';i++;}else if(c==='"')q=false;else v+=c;}else if(c==='"')q=true;else if(c===','){row.push(v);v='';}else if(c==='\n'){row.push(v.replace(/\r$/,''));rows.push(row);row=[];v='';}else v+=c;}if(v||row.length){row.push(v.replace(/\r$/,''));rows.push(row);}if(!rows.length)return[];let head=rows.shift().map(x=>x.trim().toLowerCase());return rows.filter(a=>a.some(x=>x.trim())).map(a=>Object.fromEntries(head.map((h,i)=>[h,(a[i]||'').trim()])));}
  async function importFile(file){try{const csvText=await file.text(),raw=parseCsv(csvText),seen=new Set,good=[],issues=[];raw.forEach((r,i)=>{let rowErrors=[];r.student_id=(r.student_id||r.id||'').trim();r.name=(r.name||'').trim();r.term=(r.term||'').trim();if(!r.student_id)rowErrors.push('missing student_id');if(!r.name)rowErrors.push('missing name');if(!r.term)rowErrors.push('missing term');if(r.cgpa==null||r.cgpa.trim()==='')rowErrors.push('missing cgpa');else{r.cgpa=Number(r.cgpa);if(!Number.isFinite(r.cgpa)||r.cgpa<0||r.cgpa>10)rowErrors.push('cgpa must be 0–10');}for(const k of ['year','backlogs','attendance','lms','engagement','aptitude','coding','interview','placement_readiness']){if(r[k]==null||r[k].trim()===''){r[k]=null;continue;}r[k]=Number(r[k]);if(!Number.isFinite(r[k]))rowErrors.push(`${k} must be numeric`);else if(['attendance','lms','engagement','aptitude','coding','interview','placement_readiness'].includes(k)&&(r[k]<0||r[k]>100))rowErrors.push(`${k} must be 0–100`);else if(k==='backlogs'&&(!Number.isInteger(r[k])||r[k]<0))rowErrors.push('backlogs must be a non-negative integer');else if(k==='year'&&(!Number.isInteger(r[k])||r[k]<1))rowErrors.push('year must be a positive integer');}r.updated_at=(r.updated_at||'').trim();if(r.updated_at&&!validIsoTimestamp(r.updated_at))issues.push(`Row ${i+2}: updated_at is missing ISO 8601 format or contains an invalid date`);let key=`${r.student_id}|${r.term}`;if(!rowErrors.length&&seen.has(key))rowErrors.push('duplicate student_id and term');if(rowErrors.length){issues.push(`Row ${i+2}: ${rowErrors.join(', ')}`);return;}seen.add(key);r.id=r.student_id;r.program=(r.program||'').trim()||'Unspecified';r.placement=r.placement_readiness!=null?r.placement_readiness:(['aptitude','coding','interview'].every(k=>r[k]!=null)?(r.aptitude+r.coding+r.interview)/3:undefined);good.push(r);});if(!good.length)throw Error('No valid rows found. Required fields are student_id, name, term, and cgpa; see Data & quality for accepted ranges.');if(backendMode){const saved=await api('/api/import',{method:'POST',body:JSON.stringify({csv:csvText})});records=saved.students;issues.splice(0,issues.length,...(saved.issues||[]));}else records=good;imported=true;importIssues=issues;let termsIn=[...new Set(records.map(r=>r.term))].sort((a,b)=>termKey(a).localeCompare(termKey(b)));$('termSelect').innerHTML='<option value="all">All terms · latest per student</option>'+termsIn.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');$('termSelect').value='all';render();}catch(e){alert(`CSV import failed: ${e.message}`)}$('csvFile').value='';}
